SELECT

FROM RwaInstSpvProductDividend a WHERE 1 = 1

    AND a.userId = #{userId}


    AND a.instInvestorId = #{instInvestorId}


    AND a.instSpvProductId = #{instSpvProductId}


    AND a.dividendStartDate = #{dividendStartDate}


    AND a.dividendEndDate = #{dividendEndDate}


    AND a.dividendCurrency = #{dividendCurrency}


    AND a.dividendAmount = #{dividendAmount}


    AND a.state = #{state}


    AND a.remark = #{remark}


    AND a.createTime = #{createTime}


    AND a.updateBy = #{updateBy}


    AND a.updateTime = #{updateTime}

limit 1

SELECT

FROM RwaInstSpvProductDividend a WHERE 1 = 1

    AND a.userId = #{userId}


    AND a.instInvestorId = #{instInvestorId}


    AND a.instSpvProductId = #{instSpvProductId}


    AND a.dividendStartDate = #{dividendStartDate}


    AND a.dividendEndDate = #{dividendEndDate}


    AND a.dividendCurrency LIKE CONCAT('%',#{dividendCurrency}, '%')


    AND a.dividendAmount = #{dividendAmount}


    AND a.state LIKE CONCAT('%',#{state}, '%')


    AND a.remark LIKE CONCAT('%',#{remark}, '%')


    AND a.createTime = #{createTime}


    AND a.updateBy LIKE CONCAT('%',#{updateBy}, '%')


    AND a.updateTime = #{updateTime}

order by a.createTime desc
